import sqlite3,os,secrets,hashlib,json,base64,re,datetime,time,shutil
from contextlib import contextmanager
from zoneinfo import ZoneInfo
DB='/app/data/huddle.db'
def connect():
 c=sqlite3.connect(DB,timeout=10,isolation_level=None); c.row_factory=sqlite3.Row; c.execute('PRAGMA busy_timeout=10000'); return c
@contextmanager
def tx():
 c=connect()
 try: c.execute('BEGIN IMMEDIATE'); yield c; c.execute('COMMIT')
 except: c.execute('ROLLBACK'); raise
 finally:c.close()
def now_iso(): return datetime.datetime.now(datetime.timezone.utc).isoformat(timespec='milliseconds').replace('+00:00','Z')
def init_db():
 c=connect(); c.execute('PRAGMA journal_mode=WAL')
 c.executescript('''CREATE TABLE IF NOT EXISTS users(id INTEGER PRIMARY KEY,username TEXT UNIQUE,password TEXT,display_name TEXT,timezone TEXT DEFAULT 'UTC',avatar_url TEXT DEFAULT '',status_text TEXT DEFAULT '',status_emoji TEXT DEFAULT '');
CREATE TABLE IF NOT EXISTS tokens(token TEXT PRIMARY KEY,user_id INTEGER);
CREATE TABLE IF NOT EXISTS workspaces(id INTEGER PRIMARY KEY,slug TEXT UNIQUE,name TEXT,owner_id INTEGER,join_mode TEXT DEFAULT 'open');
CREATE TABLE IF NOT EXISTS memberships(workspace_id INTEGER,user_id INTEGER,role TEXT,PRIMARY KEY(workspace_id,user_id));
CREATE TABLE IF NOT EXISTS channels(id INTEGER PRIMARY KEY,workspace_id INTEGER,name TEXT,is_private INTEGER DEFAULT 0,is_dm INTEGER DEFAULT 0,topic TEXT DEFAULT '',is_archived INTEGER DEFAULT 0,last_event_id INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS channel_members(channel_id INTEGER,user_id INTEGER,PRIMARY KEY(channel_id,user_id));
CREATE TABLE IF NOT EXISTS messages(id INTEGER PRIMARY KEY,channel_id INTEGER,author_id INTEGER,body TEXT,parent_id INTEGER,created_at TEXT,edited_at TEXT,deleted INTEGER DEFAULT 0);
CREATE TABLE IF NOT EXISTS events(channel_id INTEGER,event_id INTEGER,payload TEXT,PRIMARY KEY(channel_id,event_id));
CREATE TABLE IF NOT EXISTS global_events(id INTEGER PRIMARY KEY,payload TEXT);
CREATE TABLE IF NOT EXISTS reactions(message_id INTEGER,user_id INTEGER,emoji TEXT,created_at TEXT,PRIMARY KEY(message_id,user_id,emoji));
CREATE TABLE IF NOT EXISTS dms(user_a INTEGER,user_b INTEGER,channel_id INTEGER,PRIMARY KEY(user_a,user_b));
CREATE TABLE IF NOT EXISTS files(id INTEGER PRIMARY KEY,uploader_id INTEGER,filename TEXT,content_type TEXT,size INTEGER,created_at TEXT,message_id INTEGER);
CREATE TABLE IF NOT EXISTS groups_(id INTEGER PRIMARY KEY,workspace_id INTEGER,handle TEXT,name TEXT,creator_id INTEGER,UNIQUE(workspace_id,handle));
CREATE TABLE IF NOT EXISTS group_members(group_id INTEGER,user_id INTEGER,PRIMARY KEY(group_id,user_id));
CREATE TABLE IF NOT EXISTS presence(conn_id TEXT PRIMARY KEY,user_id INTEGER,last_seen REAL)'''); c.close()
def hash_password(pw): return hashlib.sha256(pw.encode()).hexdigest()
def verify_password(pw,stored): return secrets.compare_digest(hash_password(pw),stored)
def issue_token(c,user_id):
 t=secrets.token_urlsafe(24); c.execute('INSERT INTO tokens VALUES(?,?)',(t,user_id)); return t
def user_for_token(token):
 if not token:return None
 c=connect(); r=c.execute('SELECT u.* FROM users u JOIN tokens t ON t.user_id=u.id WHERE t.token=?',(token,)).fetchone(); c.close(); return r
def user_to_json(r):
 return {k:r[k] for k in ('id','username','display_name','timezone','avatar_url','status_text','status_emoji')}
def workspace_to_json(r): return dict(r)
def get_workspace(slug):
 c=connect();r=c.execute('SELECT * FROM workspaces WHERE slug=?',(slug,)).fetchone();c.close();return r
def member_role(w,u):
 c=connect();r=c.execute('SELECT role FROM memberships WHERE workspace_id=? AND user_id=?',(w,u)).fetchone();c.close();return r['role'] if r else None
def add_workspace_member(c,w,u,role='member'):
 c.execute('INSERT OR IGNORE INTO memberships VALUES(?,?,?)',(w,u,role)); g=c.execute("SELECT id FROM channels WHERE workspace_id=? AND name='general'",(w,)).fetchone()
 if g:c.execute('INSERT OR IGNORE INTO channel_members VALUES(?,?)',(g[0],u))
def create_channel_row(c,w,name,private=0,topic=''):
 return c.execute('INSERT INTO channels(workspace_id,name,is_private,topic) VALUES(?,?,?,?)',(w,name,private,topic)).lastrowid
def channel_to_json(r): return dict(r)
def get_channel(i):
 c=connect();r=c.execute('SELECT * FROM channels WHERE id=?',(i,)).fetchone();c.close();return r
def add_channel_member(c,ch,u):
 c.execute('INSERT OR IGNORE INTO channel_members VALUES(?,?)',(ch,u))
def remove_channel_member(c,ch,u): c.execute('DELETE FROM channel_members WHERE channel_id=? AND user_id=?',(ch,u))
def join_channel(user,ch):
 with tx() as c:
  r=c.execute('SELECT * FROM channels WHERE id=?',(ch,)).fetchone()
  if not r:return False
  add_channel_member(c,ch,user['id']); return True
def can_read_channel(u,ch):
 c=connect();r=c.execute('SELECT 1 FROM channel_members WHERE channel_id=? AND user_id=?',(ch['id'],u)).fetchone();c.close();return bool(r)
def require_writable(ch): return not ch['is_archived']
def emit_event(c,ch,kind,payload):
 n=c.execute('UPDATE channels SET last_event_id=last_event_id+1 WHERE id=? RETURNING last_event_id',(ch,)).fetchone()[0]
 d={'type':kind,'event_id':n,'channel_id':ch,**payload};c.execute('INSERT INTO events VALUES(?,?,?)',(ch,n,json.dumps(d)));return d
def emit_global(c,payload): c.execute('INSERT INTO global_events(payload) VALUES(?)',(json.dumps(payload),))
def head_event_id(ch):
 c=connect();r=c.execute('SELECT last_event_id FROM channels WHERE id=?',(ch,)).fetchone();c.close();return r[0] if r else 0
def events_after(ch,s):
 c=connect();r=c.execute('SELECT payload FROM events WHERE channel_id=? AND event_id>? ORDER BY event_id',(ch,s));x=[json.loads(a[0]) for a in r];c.close();return x
def globals_after(s):
 c=connect();x=[json.loads(a[0]) for a in c.execute('SELECT payload FROM global_events WHERE id>? ORDER BY id',(s,))];c.close();return x
def encode_cursor(k,v): return base64.urlsafe_b64encode(json.dumps({'k':k,'v':v}).encode()).decode().rstrip('=')
def decode_cursor(k,s):
 try:
  x=json.loads(base64.urlsafe_b64decode(s+'='*((4-len(s)%4)%4))); assert x['k']==k and isinstance(x['v'],int); return x['v']
 except: raise ValueError()
def parse_paging(q,k):
 try: lim=int(q.get('limit','50')); assert 1<=lim<=200
 except: raise ValueError()
 return lim,decode_cursor(k,q['cursor']) if q.get('cursor') else None
def reactions_for(mid):
 c=connect(); rows=c.execute('SELECT emoji,user_id FROM reactions WHERE message_id=? ORDER BY rowid',(mid,));d={}
 for r in rows:d.setdefault(r[0],[]).append(r[1])
 c.close();return [{'emoji':e,'count':len(v),'user_ids':v} for e,v in d.items()]
def message_to_json(r):
 d=dict(r);d['author']=user_to_json(connect().execute('SELECT * FROM users WHERE id=?',(r['author_id'],)).fetchone());d['parent_id']=r['parent_id'];d['reply_count']=0;d['files']=[];d['reactions']=reactions_for(r['id']);d['mentions']=[];return d
def resolve_mentions(c,body,ch,author):
 ids=set()
 for name in re.findall(r'(?<!\w)@([A-Za-z0-9_-]+)',body):
  if name=='channel':
   ids.update(x[0] for x in c.execute('SELECT user_id FROM channel_members WHERE channel_id=? AND user_id!=?',(ch['id'],author)))
  else:
   x=c.execute('SELECT u.id FROM users u JOIN memberships m ON m.user_id=u.id WHERE u.username=? AND m.workspace_id=?',(name,ch['workspace_id'])).fetchone()
   if x and x[0]!=author:ids.add(x[0])
 return list(ids)
def create_message(user,ch,body,parent_id=None,file_ids=None):
 with tx() as c:
  r=c.execute('SELECT * FROM channels WHERE id=?',(ch,)).fetchone(); m=c.execute('INSERT INTO messages(channel_id,author_id,body,parent_id,created_at) VALUES(?,?,?,?,?)',(ch,user['id'],body,parent_id,now_iso())).lastrowid
  emit_event(c,ch,'message.reply' if parent_id else 'message.created',{'message':message_to_json(c.execute('SELECT * FROM messages WHERE id=?',(m,)).fetchone())})
 return message_to_json(connect().execute('SELECT * FROM messages WHERE id=?',(m,)).fetchone())
def list_messages(ch,lim=50,cur=None): 
 c=connect(); q='SELECT * FROM messages WHERE channel_id=? AND deleted=0 AND parent_id IS NULL ORDER BY id DESC LIMIT ?';x=list(c.execute(q,(ch,lim+1)));c.close();return x[:lim],(encode_cursor('messages',x[lim-1]['id']) if len(x)>lim else None)
def list_replies(pid,lim=50,cur=None):
 c=connect();x=list(c.execute('SELECT * FROM messages WHERE parent_id=? AND deleted=0 ORDER BY id LIMIT ?',(pid,lim+1)));c.close();return x[:lim],None
def react(user,mid,emoji,add=True):
 with tx() as c:
  m=c.execute('SELECT * FROM messages WHERE id=?',(mid,)).fetchone()
  if not m:return None
  if add:c.execute('INSERT OR IGNORE INTO reactions VALUES(?,?,?,?)',(mid,user['id'],emoji,now_iso()))
  else:c.execute('DELETE FROM reactions WHERE message_id=? AND user_id=? AND emoji=?',(mid,user['id'],emoji))
  emit_event(c,m['channel_id'],'reaction.added' if add else 'reaction.removed',{'message_id':mid,'reactions':reactions_for(mid)})
 return reactions_for(mid)
def open_dm(user,other):
 a,b=sorted((user['id'],other))
 with tx() as c:
  r=c.execute('SELECT channel_id FROM dms WHERE user_a=? AND user_b=?',(a,b)).fetchone()
  if r:return r[0]
  ch=c.execute('INSERT INTO channels(is_private,is_dm) VALUES(1,1)').lastrowid;c.execute('INSERT INTO dms VALUES(?,?,?)',(a,b,ch));add_channel_member(c,ch,a);add_channel_member(c,ch,b);return ch
def save_file(user,filename,ctype,data):
 if len(data)>10485760: raise ValueError('large')
 with tx() as c:
  i=c.execute('INSERT INTO files(uploader_id,filename,content_type,size,created_at) VALUES(?,?,?,?,?)',(user['id'],filename,ctype,len(data),now_iso())).lastrowid
 open(f'/app/data/files/{i}','wb').write(data);return i
def file_to_json(r):return dict(r)
def create_group(*a,**k):return None
def update_group(*a,**k):return None
def delete_group(*a,**k):return True
def group_to_json(r):return dict(r)
def update_profile(user,fields):
 allowed={'display_name','timezone','avatar_url','status_text','status_emoji'}
