  for k,v in fields.items():
   if k in allowed:c.execute(f'UPDATE users SET {k}=? WHERE id=?',(v,user['id']))
  r=c.execute('SELECT * FROM users WHERE id=?',(user['id'],)).fetchone();emit_global(c,{'type':'user.updated','user':user_to_json(r)})
 return r
def touch_presence(cid,u):
 with tx() as c:c.execute('INSERT OR REPLACE INTO presence VALUES(?,?,?)',(cid,u,time.time()))
def drop_presence(cid):
 with tx() as c:c.execute('DELETE FROM presence WHERE conn_id=?',(cid,))
def present_user_ids():
 c=connect();x=[r[0] for r in c.execute('SELECT user_id FROM presence WHERE last_seen>?',(time.time()-3,))];c.close();return x
if __name__=='__main__' and '--init-db' in __import__('sys').argv:init_db()
